#work tbody tr { will-change: transform; }
#work { min-width: 900px; }

/* Two series, two scales. The right-hand axis label sits at the right so it reads
   against the axis it belongs to. */
.chart-axis .axis.right { text-align: right; }
.series-line { fill: none; stroke-width: 1.5; vector-effect: non-scaling-stroke;
               stroke-linejoin: round; stroke-linecap: round; }
svg.chart.dual { height: 96px; }
/* The growth chart earns the full width: a month at daily resolution squeezed into a
   third of the row is a smear. */
.chart-card.wide { grid-column: 1 / -1; }


/* --- the corpus section: two scopes, the rules that fire, the skills that load --- */
.chart-card.scope dl { display: grid; grid-template-columns: 1fr auto; gap: 0; margin: 0; }
.chart-card.scope dt { padding: 4px 0; color: var(--ink-2); font-size: 12.5px; border-bottom: 1px solid var(--rule); margin: 0; }
.chart-card.scope dd { padding: 4px 0; text-align: right; border-bottom: 1px solid var(--rule); margin: 0; }
.chart-card.scope dl > :nth-last-child(-n+2) { border-bottom: 0; }
.rate { display: flex; align-items: baseline; gap: 8px; }
.rate .big { font-size: 20px; color: var(--critical); }
.meter { height: 6px; background: var(--rule); border-radius: 999px; overflow: hidden; }
.meter > i { display: block; height: 100%; background: var(--critical); border-radius: 999px; }
/* A relative-volume bar is a length, not a segment mix: `.vol`, not `.bar`. */
.vol { display: block; height: 8px; min-width: 40px; }
.vol > i { display: block; height: 100%; border-radius: 2px; min-width: 2px; }
.vol > i.block { background: var(--critical); }
.vol > i.advise { background: var(--serious); }
.vol > i.skill { background: var(--good); }
td.volcell { width: 38%; min-width: 120px; }
table.plain td { padding: 4px 6px; font-size: 12.5px; }
table.plain tbody tr:hover { background: none; }
ul.zero { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 3px; }
ul.zero li { display: flex; justify-content: space-between; gap: 12px; font-size: 12.5px; padding: 3px 0; border-bottom: 1px dotted var(--rule); }
ul.zero li:last-child { border-bottom: 0; }
.chip.block, .chip.advise { padding: 1px 6px; font-size: 11px; font-weight: 600; border-radius: 3px; }
.chip.block { border-color: var(--critical); color: var(--critical); }
.chip.advise { border-color: var(--serious); color: var(--serious); }
.dim { color: var(--muted); }
#fleet-corpus h3 { font-size: 14px; margin: 18px 0 8px; }
/* Collapsed by default: the section is depth, and the members grid is what the page
   is opened for — it has to land above the fold. The summary still carries the range
   line, so a closed section says what it holds and who is counted. */
details.fold > summary { cursor: pointer; list-style: none; }
details.fold > summary::-webkit-details-marker { display: none; }
details.fold > summary h2::before { content: "▸ "; color: var(--muted); font-size: 12px; }
details.fold[open] > summary h2::before { content: "▾ "; }
#fleet-corpus-range { font-size: 12px; color: var(--muted); margin: 0 0 10px; }
#fleet-corpus-members { min-width: 860px; }

tr.pending-row td { color: var(--muted); }
#fleet-progress { font-size: 12px; color: var(--muted); margin: 0 0 10px; }
.pill { font-size: 12px; border: 1px solid var(--border); border-radius: 999px;
        padding: 2px 9px; color: var(--ink-2); background: var(--surface); }
.pill.warn-pill { border-color: var(--serious); color: var(--serious); }
.pill.stop-pill { border-color: var(--critical); color: var(--critical); }
.notice { border-left: 3px solid var(--serious); background: var(--surface);
          padding: 10px 14px; border-radius: 0 8px 8px 0; margin-bottom: 14px; color: var(--ink-2); }
.notice b { color: var(--ink); }

.empty { padding: 22px; text-align: center; color: var(--muted); }
.err { border-left: 3px solid var(--critical); background: var(--surface);
       padding: 10px 14px; border-radius: 0 8px 8px 0; margin-bottom: 14px; }
/* The explainer rides in the topbar and opens OVER the page. It answers a question
   you have once — "what is this thing doing with my credential" — and as a block in
   the flow it pushed the content it explains down the screen on every load after
   that one. `position: fixed` rather than absolute: the topbar is sticky, and an
   absolutely-positioned panel inside it is clipped by the bar's own height. */
details.setup { position: relative; }
details.setup > summary { cursor: pointer; list-style: none; font-size: 12px;
                border: 1px solid var(--border); border-radius: 999px;
                padding: 2px 9px; color: var(--ink-2); background: var(--surface); }
details.setup > summary::-webkit-details-marker { display: none; }
details.setup > summary:hover { border-color: var(--ink-2); color: var(--ink); }
details.setup[open] > summary { border-color: var(--ink-2); color: var(--ink); }
