import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { parseDescriptor, FLEET_KINDS, KINDS } from '../src/read/contributions.mjs';

// A pack's dashboard descriptor must be one the DASHBOARD'S OWN READER accepts.
//
// NOT a second copy of the schema. `dashboard-descriptor.schema.json` is a real JSON
// Schema the file points at with `$schema`, and ordinary tooling validates shape
// against it; re-implementing that here would be a coded validation vocabulary beside
// a perfectly good schema. What this asserts is the thing a schema structurally
// cannot: that `parseDescriptor` — the exact function the page runs — can USE the
// file, and that the ids the views select by resolve to widgets that exist.
//
// The failure it exists to catch is silent in the worst way. A descriptor the reader
// rejects does not break the page: by design it becomes one apologetic line on that
// pack's card, in a member's browser, where nobody authoring the pack will ever see
// it. The pack ships, converges to the fleet, and reports nothing anywhere.
//
// BLOCKING, because there is no window in which an unusable descriptor is correct,
// and because the pack author is the only person who can fix it.
//
// Scope is the descriptors a repo can actually FIX: the canon's own `packs/` when run
// from the canon, and a member's own `.claudinite/local/packs/`. The vendored mount is
// deliberately outside it — `.claudinite/shared/` is read-only to a member, so a canon
// descriptor's fault is not a member's to be blocked on, and the canon's own run is
// where it goes red. Run from canon the mount does not exist and the skip never fires,
// which is the right answer in both places.
//
// Taken from `ctx.allFiles`, so a descriptor added but not yet tracked is covered too.
const DESCRIPTOR = /^(\.claudinite\/local\/)?packs\/([^/]+)\/dashboard\.json$/;
const MOUNT = '.claudinite/shared/';

const rule = {
  id: 'descriptor-usable',
  severity: 'blocking',
  description: "a pack's dashboard.json is one the dashboard's own reader can use",
  doc: 'packs/claudinite-dashboard/dashboard-descriptor.schema.json',
  why: 'a descriptor the reader rejects renders as an apology on a card in someone else\'s browser — the pack ships, converges, and reports nothing, with nothing going red anywhere the author looks',

  run(ctx) {
    const out = [];
====
105:  adoptionHandover: [
106-    {
107-      step: 'Enable GitHub Pages with source "GitHub Actions" — this repo\'s /settings/pages',
108-      breaks: 'the publish-pages task pushes the build, and its deploy run then fails — the task parks at needs-human-action naming this',
109-      done: 'the Pages URL serves the dashboard, and a publish-pages run converged done',
110-    },
111-    // ONE entry, not the four mechanical steps, because for many deployments the right
112-    // answer is "nothing" — a member's own dashboard read with a pasted token is on the
113-    // same 5,000/hour as a signed-in one. What every adopter does have to meet is the
114-    // DECISION, since until someone makes it their page reads GitHub anonymously; four
115-    // unconditional checkboxes that are mostly no-ops teach the reader to skim exactly
116-    // the list that exists to stop them skimming. The mechanics live in the README,
117-    // where they are read at the moment the answer is yes — and a `step` becomes one
118-    // checkbox in somebody's handover issue, so spelling them here would put six
119-    // actions and a rationale inside one box (basics' `writing-handover-issues`).
120-    {
121-      step: 'Decide how this dashboard authenticates its viewers: leave it on the pasted-token box, or turn on '
122-        + 'Sign in with GitHub — the pack README\'s "Turning sign-in on" is that checklist.',
123-      breaks: 'nothing fails, but a viewer who has not pasted a token reads GitHub anonymously at 60 requests/hour per IP — '
124-        + 'which one fleet sweep exceeds, so the page serves cached data or empty rows until the hour rolls',
125-      done: 'a signed-in viewer sees the rate pill read “…/5000 · user”, or this repo has recorded that the token box is '
126-        + 'this deployment\'s answer',
127-    },
128-  ],
129-
130-  // Seeded, never converged: `.github/workflows/` cannot be written by the nightly, so
131-  // this arrives once, at adoption, and the repo owns it from there. Only `uses:` steps,
132-  // for exactly that reason — the part that cannot be updated holds nothing to update.
133-  seedOps: [
134-    {
135-      template: 'stubs/workflows/claudinite-dashboard-pages.yml',
136-      dest: '.github/workflows/claudinite-dashboard-pages.yml',
137-    },
138-  ],
