      : `this repo${config.defaultRepo ? ` (${config.defaultRepo})` : ''}`;
process.stdout.write(
  `Built ${OUT}\n`
  + `  mode: ${fleetMode ? 'fleet-dashboard' : 'repo-dashboard'} (declared)\n`
  + `  covers: ${covers}\n`

