1	// The shell: configure, authenticate, and route between the two views.
2	//
3	// TWO MODES, DECIDED BY THE DEPLOYMENT'S SHAPE. A config that says where more than one
4	// member comes from — an `owner` to enumerate, a roster artifact, an explicit list — is
5	// a FLEET deployment and opens on the overview; anything else is one repo's own page
6	// and opens straight on it, with no pointless one-row fleet view. Not a mode switch
7	// anyone sets: the roster source IS the mode, so there is nothing to keep in step.
8	//
9	// ROUTING WITHIN A MODE IS THE URL. `?repo=` is the deep dive, its absence the landing
10	// view, so every view is a link someone can send and the back button works.
11	
12	import * as gh from './read/github.mjs';
13	import * as auth from './read/auth.mjs';
14	import { loadConfig, resolveRoster, isFleetConfig } from './read/config.mjs';
15	import { clearAll, stats } from './read/cache.mjs';
16	import { planPolicy, credentialAdvice, MINUTE_MS } from './read/budget.mjs';
17	import { SIGN_IN_VARS } from './read/signin-vars.mjs';
18	import { $, el, resetCountUps } from './render/ui.mjs';
19	import { loadRepo } from './views/view-repo.mjs';
20	import { loadFleet } from './views/view-fleet.mjs';
21	
22	let CONFIG = null;
23	let ROSTER = [];
24	// The roster's own members the fleet does not act on — the deployment's exclude list,
25	// resolved to the names it matched. They are drawn, greyed, rather than dropped.
26	let IGNORED = [];
27	
28	const showError = (msg) => $('errors').append(el('div', { className: 'err', textContent: msg }));
29	const showNotice = (msg) => $('errors').append(el('div', { className: 'notice', textContent: msg }));
30	
31	// --- rate budget ----------------------------------------------------------------
32	
33	// How this load will be paid for, decided BEFORE it starts. The budget is whatever
34	// GitHub last told us — carried across page loads, and confirmed by the free
35	// `/rate_limit` preflight when it has aged — so a fresh tab plans on the real number
36	// instead of discovering the limit by running into it.
37	async function planBudget(token) {
38	  const carried = gh.restoreRate();
39	  // The preflight costs no primary budget. Skipped only when the carried number is
40	  // young enough to still be true.
41	  if (!Number.isFinite(gh.rate.remaining) || Date.now() - (carried?.at ?? 0) > 2 * MINUTE_MS) {
42	    await gh.preflightRate(token);
43	  }
44	  const plan = planPolicy({
45	    remaining: gh.rate.remaining,
46	    limit: gh.rate.limit,
47	    reset: gh.rate.reset,
48	    memberCount: wantsFleet() ? ROSTER.length : 1,
49	  });
50	  gh.setPolicy(plan);
51	  return plan;
52	}
53	
54	// The pill is the honest version of "why is this not fresh". A page that quietly
55	// serves an hour-old fleet without saying so is worse than one that refuses.
56	//
57	// It is LIVE, not a reading taken at the start. The plan is decided before the sweep
58	// and the sweep is what spends the budget, so a pill drawn once — as this was — shows
59	// the viewer the number from before every request that would have changed it. The
60	// figure a viewer opens this for is what is left NOW.
61	//
62	// The plan itself is not re-decided mid-load: this load reads under the policy it was
63	// planned with, and re-planning halfway would make a row's freshness depend on where
64	// in the sweep it happened to land. Only the number moves.
65	let currentPlan = null;
66	let pillQueued = false;
67	
68	function renderRatePill(plan = currentPlan) {
69	  if (!plan) return;
70	  currentPlan = plan;
71	  const pill = $('rate');
72	  pill.hidden = false;
73	  pill.className = `pill${plan.mode === 'frozen' || plan.mode === 'scarce' ? ' stop-pill' : (plan.mode === 'low' || plan.mode === 'tight' ? ' warn-pill' : '')}`;
74	  const left = Number.isFinite(gh.rate.remaining) ? `${gh.rate.remaining}/${gh.rate.limit ?? '?'}` : 'budget unknown';
75	  const held = plan.minAge > 0 ? ` · cached ${Math.round(plan.minAge / MINUTE_MS)}m` : '';
76	  const spent = gh.rate.spent ? ` · −${gh.rate.spent} this load` : '';
77	  pill.textContent = `${left} · ${plan.tier}${held}${spent}`;
78	  pill.title = `${plan.reason}\nthis load so far: ${gh.rate.spent} spent, ${gh.rate.revalidated} revalidated free, ${gh.rate.served} from cache`;
79	}
80	
81	// A fleet sweep can restate the budget eighty times in a few seconds. Redrawing the
82	// pill on each would be eighty layouts for a number the eye reads once, so the
83	// arrivals are coalesced onto the next frame.
84	function ratePillLater() {
85	  if (pillQueued || !currentPlan) return;
86	  pillQueued = true;
87	  const draw = () => { pillQueued = false; renderRatePill(); };
88	  if (typeof requestAnimationFrame === 'function') requestAnimationFrame(draw);
89	  else draw();
90	}
91	
92	const repoParam = () => new URL(location.href).searchParams.get('repo');
93	// The fleet view is what a fleet DEPLOYMENT opens on, decided by the config's shape
94	// rather than by how many members the enumeration happened to return: a fleet whose
95	// roster read failed, or one that is momentarily down to a single readable member, is
96	// still a fleet page and must say so rather than silently becoming that member's own.
97	const wantsFleet = () => !repoParam() && isFleetConfig(CONFIG);
98	const currentRepo = () => repoParam() || CONFIG?.defaultRepo || ROSTER[0] || '';
99	
100	function go(repo) {
101	  const url = new URL(location.href);
102	  if (repo) url.searchParams.set('repo', repo);
103	  else url.searchParams.delete('repo');
104	  history.pushState(null, '', url);
105	  render();
106	}
107	
108	// --- chrome ---------------------------------------------------------------------
109	
110	// Where the credential is kept, offered beside every sign-in and left reachable from
111	// the account menu afterwards: the viewer is the only party who knows whether this
112	// browser is theirs alone, and the answer is worth changing later without signing out
113	// to do it.
114	function rememberBox() {
115	  const input = el('input', { type: 'checkbox', checked: auth.isRemembered() });
116	  input.addEventListener('change', () => auth.setRemember(input.checked));
117	  return el('label', {
118	    className: 'remember',
119	    title: 'Keep the credential in this browser after the tab closes. Leave it off on a shared machine.',
120	  }, [input, ' Remember me']);
121	}
122	
123	// The gate's controls, which are the only sign-in surface the page has — and signing
124	// in is the only route to a credential. A deployment whose owner has not configured
125	// the pair cannot sign anybody in, so the gate says THAT, naming the two variables:
126	// the alternative was a paste box telling every viewer to go and mint a PAT, which is
127	// worse than the thing sign-in replaced and was what a deployment shipped with until
128	// somebody turned sign-in on. An unconfigured dashboard is not finished being set up,
129	// and the screen is the one place the person who can finish it is standing.
130	function renderGate() {
131	  const box = $('signin-controls');
132	  box.replaceChildren();
133	
134	  if (auth.isOAuthConfigured(CONFIG)) {
135	    $('signin-heading').textContent = wantsFleet() ? 'Sign in to read this fleet' : 'Sign in to read this repository';
136	    $('signin-how').textContent = 'GitHub asks you to authorize this page once. Everything afterwards '
137	      + 'runs as you, with exactly the repositories your account can already see.';
138	    box.append(
139	      el('button', { className: 'primary', textContent: 'Sign in with GitHub', onclick: () => auth.beginSignIn(CONFIG) }),
140	      rememberBox(),
141	    );
142	    return;
143	  }
144	  $('signin-heading').textContent = 'This dashboard is not finished being set up';
145	  $('signin-how').textContent = 'Sign in is the only way in, and this deployment has not configured it, so there is '
146	    + `nothing here to sign in with yet. Its owner sets the repository variables ${SIGN_IN_VARS.clientId} and `
147	    + `${SIGN_IN_VARS.exchangeUrl} — the pack README's "Turning sign-in on" is that checklist.`;
148	}
