1	// Where the page gets its deployment-specific facts. Everything host-specific lives
2	// in a `dashboard.config.json` beside the page, never in the code — the same mounted
3	// dashboard serves a member repo checked out locally and a fleet-wide Pages site,
4	// and only the config differs.
5	//
6	// THE ROSTER IS NORMALLY NOT A LIST. A fleet deployment names an `owner` and the page
7	// enumerates that owner's repos AS THE VIEWER, so the membership is decided at read
8	// time by what this person can actually see. That is what keeps a fleet page from
9	// leaking a repo's existence to someone without access, and it is why no repo list is
10	// baked into any file here. An explicit `repos` list and a `rosterUrl` artifact are
11	// both still accepted — a deployment that wants a fixed set says so.
12	//
13	// Absent config is a valid deployment, not a broken one: it means whatever repo the URL
14	// names, and a gate that says sign-in has not been configured. So every key here is
15	// optional and every miss is a plain default — every key EXCEPT `mode`, which the build
16	// requires and refuses to guess; see `resolveMode`.
17	//
18	// Shape:
19	//   {
20	//     "mode":        "repo",                             // "repo" | "fleet" — REQUIRED, no default
21	//     "clientId":    "Iv1.abc123",                       // GitHub App / OAuth App client id
22	//     "exchangeUrl": "https://…/github-oauth",           // the code→token endpoint
23	//     "redirectUri": "https://owner.github.io/Repo/",    // defaults to this page's URL
24	//     "scope":       "repo",                             // classic OAuth Apps only
25	//     "rosterUrl":   "./fleet-roster.GENERATED.json",    // the repo selector's source
26	//     "repos":       ["owner/a", "owner/b"],             // an inline roster instead
27	//     "defaultRepo": "owner/a",
28	//     "rates":       { "claude-opus-5": { "in": 15, "cacheRead": 1.5, "out": 75 } }
29	//   }
30	
31	export const DEFAULTS = {
32	  // WHICH DASHBOARD THIS IS, and the one key with no default. `repo` is this repo's own
33	  // page; `fleet` is the overview across a roster. Silence used to mean `repo`, which
34	  // made a fleet deployment that lost its roster source publish as a one-repo page and
35	  // look intentional — so the build refuses to publish a declaration that does not say.
36	  // Null here is not a default: it is what a locally-served checkout with no config file
37	  // at all reads, and `isFleetConfig` renders that as one repo's page.
38	  mode: null,
39	  clientId: null,
40	  exchangeUrl: null,
41	  redirectUri: null,
42	  scope: null,
43	  rosterUrl: null,
44	  repos: [],
45	  // Whose repos this deployment covers, enumerated as the viewer, and which of them are
46	  // not in the fleet. Both optional: unset means this is one repo's own page.
47	  owner: null,
48	  exclude: [],
49	  defaultRepo: null,
50	  // USD per MILLION tokens, per model, per counter — the one deployment-specific fact
51	  // behind every dollar figure the page shows. Null is a supported state and not a
52	  // broken one: an unpriced page still counts tokens, and says which key to set.
53	  rates: null,
54	};
55	
56	export async function loadConfig(url = './dashboard.config.json') {
57	  try {
58	    const res = await fetch(url, { cache: 'no-store' });
59	    if (!res.ok) return { ...DEFAULTS };
60	    return { ...DEFAULTS, ...(await res.json()) };
61	  } catch {
62	    return { ...DEFAULTS };
63	  }
64	}
65	
66	// The repo list for the selector. Three sources, in precedence order: an explicit
67	// inline list, a roster artifact, or nothing — and "nothing" is a single-repo
68	// deployment, which is the member case.
69	//
70	// A roster is read for its KEYS under `repos` when it is a fleet artifact (the shape
71	// Shepherd already generates), or as a plain array of names. Both are accepted
72	// because the artifact's job is not to serve this page and its shape is not ours to
73	// dictate.
74	export function rosterFrom(doc) {
75	  if (Array.isArray(doc)) return doc.filter((x) => typeof x === 'string');
76	  if (Array.isArray(doc?.repos)) return doc.repos.filter((x) => typeof x === 'string');
77	  if (doc?.repos && typeof doc.repos === 'object') return Object.keys(doc.repos);
78	  return [];
79	}
80	
81	export async function loadRoster(config) {
82	  if (config.repos?.length) return config.repos;
83	  if (!config.rosterUrl) return [];
84	  try {
85	    const res = await fetch(config.rosterUrl, { cache: 'no-store' });
86	    if (!res.ok) return [];
87	    return rosterFrom(await res.json());
88	  } catch {
89	    return [];
90	  }
91	}
92	
93	// The two dashboards this pack builds. A deployment is one or the other and says so.
94	export const MODES = Object.freeze(['repo', 'fleet']);
95	
96	// Whether a config names anywhere for members to come from. Both spellings of the same
97	// idea travel together on purpose: the BUILD reads `rosterFile`, a path inside the repo,
98	// and the PAGE reads `rosterUrl`, a URL beside it — a guard that knew only one would
99	// read a legacy fleet declaration as naming nothing. A single-entry `repos` is this
100	// repo, named, and not a roster.
101	export const hasRosterSource = (config) =>
102	  Boolean(config?.owner || config?.rosterUrl || config?.rosterFile || (config?.repos?.length ?? 0) > 1);
103	
104	// The mode, or a throw. This is the only place the judgment lives, so the build and the
105	// page cannot drift into two matching-looking expressions that disagree at one input.
106	//
107	// It refuses three things, and the third is the one worth having: a mode that
108	// CONTRADICTS the rest of the config. `fleet` naming no roster source would publish a
109	// fleet page over nothing; `repo` beside an owner would silently ignore the owner. Both
110	// are a deployment that believes something the site is not doing, which is exactly the
111	// failure the key exists to make loud.
112	export function resolveMode(config) {
113	  const mode = config?.mode ?? null;
114	  if (mode === null) {
115	    throw new Error(
116	      'this deployment does not say which dashboard it is: set "mode" to "repo" (this repo\'s own page) '
117	      + 'or "fleet" (the overview) in the claudinite-dashboard config. There is no default — silence used to '
118	      + 'mean "repo", which let a fleet deployment that lost its roster publish as one repo and look intentional.');
119	  }
120	  if (!MODES.includes(mode)) {
121	    throw new Error(`claudinite-dashboard mode "${mode}" is not a mode — it is "repo" or "fleet".`);
122	  }
123	  if (mode === 'fleet' && !hasRosterSource(config)) {
124	    throw new Error(
125	      'mode is "fleet" but the config names no roster source — add "owner" (enumerated as the viewer), '
126	      + 'or "repos"/"rosterUrl"/"rosterFile". A fleet page over nothing is the state this guard exists to catch.');
127	  }
128	  if (mode === 'repo' && hasRosterSource(config)) {
129	    throw new Error(
130	      'mode is "repo" but the config names a roster source, which a repo page never reads — '
131	      + 'drop it, or set mode to "fleet".');
132	  }
133	  return mode;
134	}
135	
136	// Whether this deployment is a FLEET one. It READS the stated mode rather than inferring
137	// it from the roster: what a deployment covers is a thing it declares, not a thing
138	// deduced from which other keys happen to be present.
139	export const isFleetConfig = (config) => config?.mode === 'fleet';
140	
141	// Whether a NAME is on the deployment's exclude list — the Shepherd fleet's "ignore
142	// this repo". It takes either spelling, because a member writes whichever reads
143	// naturally in its own declaration.
144	//
145	// IGNORED IS A STATE, NOT A FILTER (owner, 2026-09-13). Every repo the viewer can see
146	// belongs on the fleet page, including the ones the fleet does not act on: an ignored
147	// repo and an archived one are drawn greyed, with their core GitHub facts and a way
148	// back into the fleet, rather than left off a page whose reader then cannot tell them
149	// from a repo that does not exist. What ignoring buys is that no fleet OPERATION

